import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import * as Toggle from "../../../foldkit/ui/toggle";
import { toggleGroupItemClasses, toggleGroupRootClasses } from "./view";

export {
  toggleGroupIconClasses,
  toggleGroupItemClasses,
  toggleGroupRootClasses,
} from "./view";

export type ToggleGroupStyle = Readonly<Record<string, string>>;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  ariaLabel?: string | undefined;
  className?: string | undefined;
  style?: ToggleGroupStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  value: string;
  pressedValues: readonly string[];
  onPressedChange: ParentMessage;
  ariaLabel: string;
  children: readonly Html[];
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: ToggleGroupStyle | undefined;
}>;

const cn = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const isPressed = (pressedValues: readonly string[], value: string): boolean =>
  pressedValues.includes(value);

export const rootView = <ParentMessage>({
  children,
  ariaLabel,
  className,
  style,
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      h.Attribute("role", "group"),
      ...(ariaLabel === undefined ? [] : [h.AriaLabel(ariaLabel)]),
      ...(style === undefined ? [] : [h.Style(style)]),
      h.Class(cn(toggleGroupRootClasses, className)),
    ],
    children
  );
};

export const itemView = <ParentMessage>({
  value,
  pressedValues,
  onPressedChange,
  ariaLabel,
  children,
  disabled = false,
  className,
  style,
}: ItemViewConfig<ParentMessage>): Html =>
  Toggle.view<ParentMessage>({
    value,
    pressed: isPressed(pressedValues, value),
    onPressedChange,
    ariaLabel,
    disabled,
    // NOTE: The public wrapper API is className; Foldkit Toggle still accepts classes.
    classes: cn(toggleGroupItemClasses, className),
    style,
    children,
  });

export const toggleGroupRootClasses =
  "inline-flex items-center rounded-lg border border-gray-200 bg-white p-1 shadow-sm";

export const toggleGroupItemClasses =
  "h-8 w-8 rounded-md border-0 shadow-none";

export const toggleGroupIconClasses = "h-4 w-4";

import { Schema as S } from "effect";
import { Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { describe, expect, test } from "vitest";

import * as ToggleGroup from "./index";

const ClickedAlign = m("ClickedAlign", { value: S.String });
const Message = S.Union([ClickedAlign]);
type Message = typeof Message.Type;

const icon = (label: string): Html => {
  const h = html<Message>();

  return h.span([h.Class(ToggleGroup.toggleGroupIconClasses)], [label]);
};

const view = (pressedValues: readonly string[]): Html =>
  ToggleGroup.rootView<Message>({
    ariaLabel: "Text alignment",
    children: [
      ToggleGroup.itemView<Message>({
        value: "left",
        pressedValues,
        ariaLabel: "Align left",
        onPressedChange: ClickedAlign({ value: "left" }),
        children: [icon("L")],
      }),
      ToggleGroup.itemView<Message>({
        value: "center",
        pressedValues,
        ariaLabel: "Align center",
        onPressedChange: ClickedAlign({ value: "center" }),
        children: [icon("C")],
      }),
    ],
  });

describe("Toggle Group registry view", () => {
  test("renders grouped toggle buttons with selected value state", () => {
    Scene.scene(
      {
        update: (
          _model: readonly string[],
          message: Message
        ): readonly [readonly string[], []] => {
          expect(message._tag).toBe("ClickedAlign");
          return [[message.value], []];
        },
        view,
      },
      Scene.with(["left"]),
      Scene.expect(Scene.role("group", { name: "Text alignment" })).toExist(),
      Scene.expect(Scene.role("button", { name: "Align left" })).toHaveAttr(
        "aria-pressed",
        "true"
      ),
      Scene.expect(Scene.role("button", { name: "Align center" })).toHaveAttr(
        "aria-pressed",
        "false"
      ),
      Scene.click(Scene.role("button", { name: "Align center" })),
      Scene.expect(Scene.role("button", { name: "Align left" })).toHaveAttr(
        "aria-pressed",
        "false"
      ),
      Scene.expect(Scene.role("button", { name: "Align center" })).toHaveAttr(
        "aria-pressed",
        "true"
      )
    );
  });
});
